package org.apache.commons.math3.optimization.linear;

import org.apache.commons.math3.linear.Array2DRowRealMatrix;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.linear.LinearConstraint;
import org.apache.commons.math3.optimization.linear.LinearObjectiveFunction;
import org.apache.commons.math3.optimization.linear.Relationship;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.ArrayList;
import java.util.Collection;

public class AgentBRT_Math_33_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Define the objective function
        LinearObjectiveFunction objectiveFunction = new LinearObjectiveFunction(new double[] {0.0000001, 1.0}, 0);

        // Define the constraints
        Collection<LinearConstraint> constraints = new ArrayList<>();
        constraints.add(new LinearConstraint(new double[] {1.0, 0.0}, Relationship.LEQ, 1.0));
        constraints.add(new LinearConstraint(new double[] {0.0, 1.0}, Relationship.LEQ, 1.0));

        // Create the SimplexTableau
        SimplexTableau tableau = new SimplexTableau(objectiveFunction, constraints, GoalType.MINIMIZE, false, 0.0000001);

        // Call the method that should drop the phase 1 objective
        tableau.dropPhase1Objective();

        // Check if the column with the small positive entry was dropped
        // Before the fix, this column would not be dropped due to precision issues
        assertEquals("Column with small positive entry should be dropped", 2, tableau.getWidth());
    }
}

