        double[][] data = {
            {0.0000001, 1.0, 0.0},  // Objective function row
            {1.0, 0.0, 1.0},        // Constraint rows
            {0.0, 1.0, 0.0}
        };
        RealMatrix matrix = new Array2DRowRealMatrix(data);
        SimplexTableau tableau = new SimplexTableau(matrix, null, null, false, 0.0000001);

        // Call the method that should drop the phase 1 objective
        tableau.dropPhase1Objective();

        // Check if the column with the small positive entry was dropped
        // Before the fix, this column would not be dropped due to precision issues
        assertEquals("Column with small positive entry should be dropped", 2, tableau.getWidth());
    }
}

